    /// RFC 4231 §4.2.
    #[test]
    fn rfc4231_case_1_short_key() {
        let key = [0x0bu8; 20];
        assert_eq!(
            to_hex(&hmac_sha256(&key, b"Hi There")),
            "b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7"
        );
    }

    /// RFC 4231 §4.3 — key shorter than the digest.
    #[test]
    fn rfc4231_case_2_jefe() {
        assert_eq!(
            to_hex(&hmac_sha256(b"Jefe", b"what do ya want for nothing?")),
            "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843"
        );
    }

    /// RFC 4231 §4.4 — 50-byte message, spans two blocks with the pad.
    #[test]
    fn rfc4231_case_3_repeated_data() {
        let key = [0xaau8; 20];
        let data = [0xddu8; 50];
        assert_eq!(
            to_hex(&hmac_sha256(&key, &data)),
            "773ea91e36800e46854db8ebd09181a72959098b3ef8c122d9635514ced565fe"
        );
    }

    /// RFC 4231 §4.5 — 25-byte ascending key.
    #[test]
    fn rfc4231_case_4_ascending_key() {
        let key: Vec<u8> = (1u8..=25).collect();
        let data = [0xcdu8; 50];
        assert_eq!(
            to_hex(&hmac_sha256(&key, &data)),
            "82558a389a443c0ea4cc819899f2083a85f0faa3e578f8077a2e3ff46729665b"
        );
    }

    /// RFC 4231 §4.7 — 131-byte key, hashed before use.
    #[test]
    fn rfc4231_case_6_long_key() {
        let key = [0xaau8; 131];
        let data = b"Test Using Larger Than Block-Size Key - Hash Key First";
        assert_eq!(
            to_hex(&hmac_sha256(&key, data)),
            "60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54"
        );
    }

    /// RFC 4231 §4.8 — long key *and* long message.
    #[test]
    fn rfc4231_case_7_long_key_long_message() {
        let key = [0xaau8; 131];
        let data = b"This is a test using a larger than block-size key and a larger \
                     than block-size data. The key needs to be hashed before being \
                     used by the HMAC algorithm.";
        assert_eq!(
            to_hex(&hmac_sha256(&key, data)),
            "9b09ffa71b942fcb27635fbcd5b0e944bfdc63644f0713938a7f51535c3a35e2"
        );
    }

    /// 64 bytes is used verbatim; 65 crosses into the hash-the-key branch.
    #[test]
    fn block_size_key_boundary() {
        let msg = b"block-size key boundary";
        assert_eq!(
            to_hex(&hmac_sha256(&[0xaau8; 64], msg)),
            "41f727b8436ee2c52ddae4d5200e3d5b57018dbde22b3970da65cd61b96c0f39"
        );
        assert_eq!(
            to_hex(&hmac_sha256(&[0xaau8; 65], msg)),
            "eca46d7d23f55b1e48237223496b5b064daee7d329f079c8901b0f03079e93cf"
        );
    }

    #[test]
    fn empty_key_and_message() {
        assert_eq!(
            to_hex(&hmac_sha256(b"", b"")),
            "b613679a0814d9ec772f95d778c35fc5ff1697c493715653c6c712144292c5ad"
        );
    }

    #[test]
    fn concat_matches_joined_message() {
        let key = b"stream-token-key";
        let a = b"community:main|".to_vec();
        let b = vec![7u8; 200];
        let c = b"|1753574400000".to_vec();

        let mut joined = Vec::new();
        joined.extend_from_slice(&a);
        joined.extend_from_slice(&b);
        joined.extend_from_slice(&c);

        assert_eq!(
            hmac_sha256_concat(key, &[&a, &b, &c]),
            hmac_sha256(key, &joined)
        );
        assert_eq!(hmac_sha256_concat(key, &[]), hmac_sha256(key, b""));
        assert_eq!(
            hmac_sha256_concat(key, &[&a, &[], &b, &[], &c]),
            hmac_sha256(key, &joined)
        );
    }

